src='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    components = []
    singleton = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            if len(cells) == 1:
                singleton.append((r, c, color))
            else:
                rs = [y for y, x in cells]
                cs = [x for y, x in cells]
                components.append((color, len(cells), min(rs), max(rs), min(cs), max(cs)))
    out = [row[:] for row in grid]
    for r, c, color in singleton:
        containers = [obj for obj in components if obj[2] <= r <= obj[3] and obj[4] <= c <= obj[5]]
        if containers:
            out[r][c] = max(containers, key=lambda obj: obj[1])[0]
        else:
            out[r][c] = bg
    return out
'''
